import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ------------------- CUDA kernel -------------------
cuda_src = r'''
extern "C" __global__
void conv_transpose2d_fp16(const __half* __restrict__ input,
                           const __half* __restrict__ weight,
                           __half* __restrict__ output,
                           int batch,
                           int in_c,
                           int out_c,
                           int in_h,
                           int in_w,
                           int k) {
    // grid.z encodes (batch * out_c)
    int bz = blockIdx.z;
    int n  = bz / out_c;          // batch index
    int oc = bz % out_c;          // output channel index

    int y = blockIdx.y * blockDim.y + threadIdx.y; // output height
    int x = blockIdx.x * blockDim.x + threadIdx.x; // output width

    int out_h = in_h + k - 1;
    int out_w = in_w + k - 1;
    if (y >= out_h || x >= out_w) return;

    float acc = 0.0f;

    // iterate over input channels and kernel positions
    for (int ic = 0; ic < in_c; ++ic) {
        for (int p = 0; p < k; ++p) {
            int in_y = y - p;          // corresponding input y
            if (in_y < 0 || in_y >= in_h) continue;
            for (int q = 0; q < k; ++q) {
                int in_x = x - q;      // corresponding input x
                if (in_x < 0 || in_x >= in_w) continue;

                // input indexing: ((n * in_c + ic) * in_h + in_y) * in_w + in_x
                int in_idx = ((n * in_c + ic) * in_h + in_y) * in_w + in_x;
                // weight indexing: ((ic * out_c + oc) * k + p) * k + q
                int w_idx = ((ic * out_c + oc) * k + p) * k + q;

                float in_val = __half2float(input[in_idx]);
                float w_val  = __half2float(weight[w_idx]);
                acc += in_val * w_val;
            }
        }
    }

    int out_idx = ((n * out_c + oc) * out_h + y) * out_w + x;
    output[out_idx] = __float2half(acc);
}
'''

# ------------------- C++ wrapper -------------------
cpp_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

void conv_transpose2d_fp16_launcher(at::Tensor input,
                                    at::Tensor weight,
                                    at::Tensor output) {
    const int batch = input.size(0);
    const int in_c  = input.size(1);
    const int in_h  = input.size(2);
    const int in_w  = input.size(3);
    const int out_c = weight.size(1);
    const int k     = weight.size(2); // kernel height (square)

    const dim3 block(16, 16);
    const dim3 grid(
        (output.size(3) + block.x - 1) / block.x,
        (output.size(2) + block.y - 1) / block.y,
        batch * out_c
    );

    conv_transpose2d_fp16<<<grid, block>>>(
        reinterpret_cast<__half*>(input.data_ptr()),
        reinterpret_cast<__half*>(weight.data_ptr()),
        reinterpret_cast<__half*>(output.data_ptr()),
        batch, in_c, out_c, in_h, in_w, k
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_THROW(cudaGetErrorString(err));
    }
}
'''

