_ext = load_inline(name='conv_transpose2d_ext',
                   cpp_sources=cpp_src,
                   cuda_sources=cuda_src,
                   functions=['conv_transpose2d_fp16_launcher'],
                   verbose=False)

# ------------------- Python wrapper -------------------
def conv_transpose2d_fp16(input: torch.Tensor, weight: torch.Tensor) -> torch.Tensor:
    """
    Custom fp16 transposed convolution (stride=1, padding=0, output_padding=0, groups=1, bias=False).
    """
    batch, in_c, in_h, in_w = input.shape
    out_c = weight.shape[1]
    k = weight.shape[2]          # kernel size (square)
    out_h = in_h + k - 1
    out_w = in_w + k - 1
    output = torch.empty(batch, out_c, out_h, out_w,
                         dtype=torch.float16, device='cuda')
    _ext.conv_transpose2d_fp16_launcher(input, weight, output)
    return output

# ------------------- Model definition -------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model using a custom CUDA kernel.
    Supports only the default ConvTranspose2d parameters:
        stride=1, padding=0, output_padding=0, groups=1, bias=False.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int):
        super(ModelNew, self).__init__()
        # weight shape for ConvTranspose2d: (in_channels, out_channels, k, k)
        self.weight = nn.Parameter(
            torch.randn(in_channels, out_channels, kernel_size, kernel_size,
                        dtype=torch.float16, device='cuda')
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv_transpose2d_fp16(x, self.weight)

# ------------------- Optional test harness -------------------
if __name__ == "__main__":
    # Example usage matching the reference test case
    batch_size = 8
    in_channels = 64
    out_channels = 64
    kernel_size = 3
    height = 1024
    width = 1024

    model = ModelNew(in_channels, out_channels, kernel_size).cuda()
    x = torch.rand(batch_size, in_channels, height, width,
                   dtype=torch.float16, device='cuda')
    y = model(x)
    print(f"Output shape: {y.shape}")
